    legacy_version!("1.21.9/1.21.10", 773, Gen::V1_21_9, v1_21_9, V1_21_9);

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_1_21_11_tables_are_the_identity_on_engine_states() {
        for raw in [0u32, 1, 86, 279, 29_670] {
            assert_eq!(V1_21_11.state(BlockStateId(raw)), raw);
        }
        assert_eq!(V1_21_11.direct_bits(), 15);
    }

    #[test]
    fn newer_versions_remap_every_engine_state_by_name() {
        for v in [&V26_1, &V26_2, &V26_3] {
            for raw in (0..aether_world::registry::blocks::STATE_COUNT as u32).step_by(997) {
                let ours = aether_world::registry::props::state_name(raw).unwrap();
                let theirs = v.state(BlockStateId(raw));
                assert!(theirs < v.state_count, "{} {ours} -> {theirs}", v.name);
            }
            assert_eq!(v.state(BlockStateId(0)), 0, "air stays air");
        }
        assert_eq!(V26_3.direct_bits(), 16, "26.3 has more than 32768 states");
    }

    #[test]
    fn packet_ids_come_from_the_versions_own_table() {
        assert_eq!(V1_21_11.packets.cb_level_chunk_with_light, 0x2C);
        assert_eq!(V1_21_11.packets.sb_move_player_pos, 0x1D);
        assert_eq!(V26_1.packets.cb_level_chunk_with_light, 45);
        assert_eq!(V26_1.packets.sb_attack, 1);
        assert_eq!(V26_3.packets.sb_swing, -1);
        assert!(V26_3.packets.sb_punch > 0);
    }

    #[test]
    fn the_built_in_registry_data_has_one_tag_per_entry() {
        for v in [&V26_1, &V26_2, &V26_3] {
            let Registries::KnownPacks { synced, data, .. } = &v.registries else {
                panic!("{} sends registries by known pack", v.name);
            };
            let raw = miniz_oxide::inflate::decompress_to_vec_zlib(data).unwrap();
            let (mut at, mut n) = (0usize, 0usize);
            while at < raw.len() {
                let len = u32::from_be_bytes(raw[at..at + 4].try_into().unwrap()) as usize;
                // Mostly compounds; a block transformer is a list.
                assert!(
                    (1..=12).contains(&raw[at + 4]),
                    "{}: entry {n} is a tag",
                    v.name
                );
                at += 4 + len;
                n += 1;
            }
            assert_eq!(at, raw.len());
            let want: usize = synced.iter().map(|(_, e)| e.len()).sum();
            assert_eq!(n, want, "{}", v.name);
        }
    }

    #[test]
    fn items_and_entities_resolve_in_every_version() {
        for v in [&V1_21_11, &V26_1, &V26_2, &V26_3] {
            assert!(v.item_id("minecraft:diamond_sword").is_some(), "{}", v.name);
            assert!(v.entity_type("minecraft:zombie").is_some(), "{}", v.name);
            assert_eq!(
                v.biome("minecraft:plains"),
                v.biome("minecraft:no_such_biome")
            );
        }
    }

    #[test]
    fn every_versions_item_wire_ids_are_dense_from_zero() {
        // The reverse tables are indexed by wire id, so a gap or a duplicate
        // in the generated data would leave a slot as air — a real item
        // silently reading as nothing — and an id past the end would once
        // have panicked. Pin both: a dense permutation of `0..len`.
        for v in [&V1_21_11, &V26_1, &V26_2, &V26_3] {
            assert!(
                v.items.windows(2).all(|w| w[0].0 < w[1].0),
                "{}: items must be sorted by name for item_id's binary search",
                v.name
            );
            let mut wires: Vec<u16> = v.items.iter().map(|(_, w)| *w).collect();
            wires.sort_unstable();
            let dense: Vec<u16> = (0..v.items.len() as u16).collect();
            assert_eq!(wires, dense, "{}: wire ids must be 0..len", v.name);

            let tables = v.item_tables();
            assert_eq!(tables.from_wire.len(), v.items.len(), "{}", v.name);
            assert!(
                tables.names_by_wire.iter().all(Option::is_some),
                "{}: a dense table has no empty slot",
                v.name
            );
        }
    }

    /// The O(n) scan `item_name` used to be, kept only to check the table.
    fn item_name_linear(v: &Version, id: i32) -> Option<&'static str> {
        v.items
            .iter()
            .find(|(_, i)| *i as i32 == id)
            .map(|(n, _)| *n)
    }

    #[test]
    fn every_version_item_round_trips_through_its_id_tables() {
        for v in [&V1_21_11, &V26_1, &V26_2, &V26_3] {
            for (name, wire) in v.items {
                let wire = *wire as i32;
                match ItemTypeId::vanilla(name) {
                    Some(engine) => {
                        assert_eq!(v.wire_item(engine), Some(wire), "{}: {name}", v.name);
                        assert_eq!(v.engine_item(wire), Some(engine), "{}: {name}", v.name);
                        assert_eq!(v.item_name(wire), Some(*name), "{}: {name}", v.name);
                    }
                    // The engine's registry is pinned to 1.21.11, so an item
                    // only 26.x has has no engine id: it becomes air there, but
                    // its name still comes back exactly — routing the name
                    // through the engine would read the client's new item as
                    // air and drop it.
                    None => {
                        assert_eq!(
                            v.engine_item(wire),
                            Some(ItemTypeId::AIR),
                            "{}: {name}",
                            v.name
                        );
                        assert_eq!(v.item_name(wire), Some(*name), "{}: {name}", v.name);
                    }
                }
            }
        }
    }

    #[test]
    fn the_tables_say_how_many_items_the_engine_registry_lacks() {
        // 1.21.11 is the engine's own pin, so it lacks nothing. 26.1 added an
        // item, 26.2 grew the block set, 26.3 more still; the exact counts are
        // pinned so a data change (or an engine repin) shows up here.
        let missing = |v: &Version| {
            v.items
                .iter()
                .filter(|&&(n, _)| ItemTypeId::vanilla(n).is_none())
                .count()
        };
        assert_eq!(missing(&V1_21_11), 0, "1.21.11 is the engine's pin");
        assert_eq!(missing(&V26_1), 1);
        assert_eq!(missing(&V26_2), 32);
        assert_eq!(missing(&V26_3), 153);
    }

    #[test]
    fn ids_outside_a_versions_tables_are_none() {
        for v in [&V1_21_11, &V26_1, &V26_2, &V26_3] {
            for beyond in [ITEM_BEYOND, ITEM_BEYOND + 1, u16::MAX] {
                assert_eq!(v.wire_item(ItemTypeId(beyond)), None, "{}", v.name);
            }
            assert_eq!(v.engine_item(-1), None, "{}", v.name);
            assert_eq!(v.engine_item(v.items.len() as i32), None, "{}", v.name);
            assert_eq!(v.engine_item(i32::MAX), None, "{}", v.name);
        }
    }

    #[test]
    fn item_name_matches_the_old_linear_scan_for_every_wire_id() {
        for v in [&V1_21_11, &V26_1, &V26_2, &V26_3] {
            // Every wire id the version has, a couple it does not, and the
            // bounds around them — identical to the O(n) scan, no exceptions.
            for id in (0..=v.items.len() as i32).chain([-1, i32::MAX]) {
                assert_eq!(v.item_name(id), item_name_linear(v, id), "{}: {id}", v.name);
            }
        }
    }
}
